    const hay = norm(`${entry.label || ''} ${entry.meta || ''} ${entry.keywords || ''}`);
    const words = q.split(/\s+/).filter(Boolean);
    if (!words.every(w => hay.includes(w))) return -1;
    let score = COMMAND_PRIORITY[entry.type] === 0 ? 4 : 0;
